"use client";

import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import Navbar from "@/components/Navbar";
import ProductForm from "@/components/ProductForm";
import ProductList from "@/components/ProductList";
import PhotoUpload from "@/components/PhotoUpload";

interface Product {
  id: string;
  name: string;
  brand?: string;
  category?: string;
  ingredients?: string;
}

interface Routine {
  id: string;
  name?: string;
  startDate: string;
  status: string;
  routineProducts: Array<{
    id: string;
    timeOfDay: "MORNING" | "NIGHT" | "BOTH";
    product: Product;
  }>;
  photos: Array<{
    id: string;
    url: string;
    type: string;
  }>;
}

export default function DashboardPage() {
  const { data: session, status } = useSession();
  const router = useRouter();
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [loading, setLoading] = useState(true);
  const [showProductForm, setShowProductForm] = useState(false);
  const [showPhotoUpload, setShowPhotoUpload] = useState(false);
  const [selectedRoutineId, setSelectedRoutineId] = useState<string | null>(null);

  useEffect(() => {
    if (status === "unauthenticated") {
      router.push("/login");
    } else if (status === "authenticated") {
      fetchRoutines();
    }
  }, [status, router]);

  const fetchRoutines = async () => {
    try {
      const response = await fetch("/api/routines");
      const data = await response.json();
      setRoutines(data.routines || []);
    } catch (error) {
      console.error("Error fetching routines:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateProduct = async (productData: {
    name: string;
    brand?: string;
    ingredients?: string;
    category?: string;
    description?: string;
  }) => {
    try {
      const response = await fetch("/api/products", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(productData),
      });

      if (response.ok) {
        setShowProductForm(false);
        // Optionally refresh products list
      }
    } catch (error) {
      console.error("Error creating product:", error);
    }
  };

  const handlePhotoUploadSuccess = () => {
    setShowPhotoUpload(false);
    fetchRoutines();
  };

  if (status === "loading" || loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-gray-600">Loading...</div>
      </div>
    );
  }

  const activeRoutine = routines.find((r) => r.status === "active") || routines[0];

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">Dashboard</h1>
          <p className="mt-2 text-gray-600">
            Track your skincare journey and see your progress
          </p>
        </div>

        {activeRoutine ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="bg-white rounded-lg shadow p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-semibold text-gray-900">
                  Current Routine
                </h2>
                <Link
                  href="/routine"
                  className="text-sm text-indigo-600 hover:text-indigo-700"
                >
                  Manage →
                </Link>
              </div>
              {activeRoutine.routineProducts.length > 0 ? (
                <ProductList
                  products={activeRoutine.routineProducts.map((rp) => ({
                    ...rp.product,
                    timeOfDay: rp.timeOfDay,
                  }))}
                />
              ) : (
                <p className="text-gray-500 text-center py-4">
                  No products in your routine yet
                </p>
              )}
            </div>

            <div className="bg-white rounded-lg shadow p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-semibold text-gray-900">
                  Recent Photos
                </h2>
                <button
                  onClick={() => {
                    setSelectedRoutineId(activeRoutine.id);
                    setShowPhotoUpload(true);
                  }}
                  className="text-sm text-indigo-600 hover:text-indigo-700"
                >
                  Upload →
                </button>
              </div>
              {activeRoutine.photos && activeRoutine.photos.length > 0 ? (
                <div className="grid grid-cols-2 gap-4">
                  {activeRoutine.photos.slice(0, 4).map((photo) => (
                    <div
                      key={photo.id}
                      className="aspect-square rounded-lg overflow-hidden border border-gray-200"
                    >
                      <img
                        src={photo.url}
                        alt={photo.type}
                        className="w-full h-full object-cover"
                      />
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-gray-500 text-center py-4">
                  No photos uploaded yet
                </p>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-white rounded-lg shadow p-6 text-center">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">
              Get Started
            </h2>
            <p className="text-gray-600 mb-6">
              Create your first skincare routine to start tracking your progress
            </p>
            <Link
              href="/routine"
              className="inline-block bg-indigo-600 text-white px-6 py-3 rounded-lg hover:bg-indigo-700 transition"
            >
              Create Routine
            </Link>
          </div>
        )}

        {showProductForm && (
          <div className="mt-8 bg-white rounded-lg shadow p-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">
              Add New Product
            </h2>
            <ProductForm
              onSubmit={handleCreateProduct}
              onCancel={() => setShowProductForm(false)}
            />
          </div>
        )}

        {showPhotoUpload && (
          <div className="mt-8 bg-white rounded-lg shadow p-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">
              Upload Photo
            </h2>
            <PhotoUpload
              routineId={selectedRoutineId || undefined}
              type="after"
              onUploadSuccess={handlePhotoUploadSuccess}
            />
          </div>
        )}
      </div>
    </div>
  );
}
