"use client";

interface Product {
  id: string;
  name: string;
  brand?: string;
  category?: string;
  ingredients?: string;
  timeOfDay?: string;
  routineProductId?: string;
}

interface ProductListProps {
  products: Product[];
  onRemove?: (productId: string, timeOfDay?: string, routineProductId?: string) => void;
  showRemove?: boolean;
  emptyLabel?: string;
}

const formatTimeOfDay = (value?: string) => {
  if (!value) return "";
  if (value === "MORNING") return "Morning";
  if (value === "NIGHT") return "Night";
  return "All Day";
};

export default function ProductList({
  products,
  onRemove,
  showRemove = false,
  emptyLabel = "No products added yet",
}: ProductListProps) {
  if (products.length === 0) {
    return (
      <div className="text-center py-6 text-gray-500 text-sm">
        {emptyLabel}
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {products.map((product) => (
        <div
          key={product.id}
          className="flex items-start justify-between p-4 bg-white border border-gray-200 rounded-lg hover:shadow-md transition"
        >
          <div className="flex-1">
            <h3 className="font-semibold text-gray-900">{product.name}</h3>
            {(product.brand || product.timeOfDay) && (
              <div className="flex flex-wrap items-center gap-2 text-sm text-gray-600 mt-1">
                {product.brand && <span>{product.brand}</span>}
                {product.timeOfDay && (
                  <span className="inline-flex items-center rounded-full bg-slate-100 px-2 py-0.5 text-xs font-medium text-slate-700">
                    {formatTimeOfDay(product.timeOfDay)}
                  </span>
                )}
              </div>
            )}
            {product.category && (
              <span className="inline-block mt-1 px-2 py-1 text-xs bg-indigo-100 text-indigo-700 rounded">
                {product.category}
              </span>
            )}
            {product.ingredients && (
              <p className="mt-2 text-sm text-gray-500 line-clamp-2">
                {product.ingredients}
              </p>
            )}
          </div>
          {showRemove && onRemove && (
            <button
              onClick={() => onRemove(product.id, product.timeOfDay, product.routineProductId)}
              className="ml-4 text-red-600 hover:text-red-700 transition"
              title="Remove product"
            >
              <svg
                className="w-5 h-5"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          )}
        </div>
      ))}
    </div>
  );
}
